@push('scripts')<script>document.querySelectorAll('[data-photo-preview]').forEach((button)=>button.addEventListener('click',()=>{document.getElementById('photoFull').src=button.dataset.photoPreview;document.getElementById('photoOverlay').classList.replace('hidden','flex')}));const photoOverlay=document.getElementById('photoOverlay');document.getElementById('closePhotoPreview').addEventListener('click',()=>photoOverlay.classList.replace('flex','hidden'));photoOverlay.addEventListener('click',(event)=>{if(event.target===photoOverlay)photoOverlay.classList.replace('flex','hidden')});document.addEventListener('keydown',(event)=>{if(event.key==='Escape')photoOverlay.classList.replace('flex','hidden')});</script>@endpush
